	/** Counts real scan openings made by a separately compiled replay; all calls delegate to the actual source. */
	private static final class CountingSource {
		private final NativeLmdbQuerySource source;
		private final long probePredicate;
		private final long buildPredicate;
		private boolean count;
		private long probeOpens, buildOpens, otherOpens;

		private CountingSource(NativeLmdbQuerySource actual, long probePredicate, long buildPredicate) {
			this.probePredicate = probePredicate;
			this.buildPredicate = buildPredicate;
			source = (NativeLmdbQuerySource) Proxy.newProxyInstance(NativeLmdbQuerySource.class.getClassLoader(),
					new Class<?>[] { NativeLmdbQuerySource.class }, (proxy, method, args) -> {
						Object result = invoke(method, actual, args);
						if (result instanceof NativeProbe probe) {
							return Proxy.newProxyInstance(NativeProbe.class.getClassLoader(),
									new Class<?>[] { NativeProbe.class }, (p, m, a) -> {
										Object value = invoke(m, probe, a);
										if ("open".equals(m.getName()) && value instanceof RecordIterator) {
											record(a);
										}
										return value;
									});
						}
						if ((method.getName().equals("statements") || method.getName().equals("lmdbStatements")
								|| method.getName().equals("statementsInEncounterOrder"))
								&& result instanceof RecordIterator) {
							record(args);
						}
						return result;
					});
		}

		private void record(Object[] args) {
			if (!count) {
				return;
			}
			int offset = args[0] instanceof StatementOrder ? 1 : 0;
			long predicate = (long) args[offset + 1];
			if (predicate == probePredicate) {
				probeOpens++;
			} else if (predicate == buildPredicate) {
				buildOpens++;
			} else {
				otherOpens++;
			}
		}

		private static Object invoke(java.lang.reflect.Method method, Object target, Object[] args) throws Throwable {
			try {
				return method.invoke(target, args);
			} catch (InvocationTargetException e) {
				throw e.getCause();
			}
		}
	}
